import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterModule } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';
import { ProjectService } from '../../../providers/project/project.service';
import { environment } from '../../../../environments/environment';

interface TechStackItem {
	key: string;
	label: string;
	icon: string;
}

@Component({
	selector: 'app-recent-work-marquee',
	standalone: true,
	imports: [CommonModule, RouterModule, TranslateModule],
	templateUrl: './recent-work-marquee.component.html',
	styleUrl: './recent-work-marquee.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecentWorkMarqueeComponent implements OnInit {
	@Input() serviceName = 'website';
	@Input() consultationLink = '/contact';
@Input() showTechStack = true;
	imagePath: string;
	baseUrl: string;

	readonly techStack: TechStackItem[] = [
		{ key: 'react', label: 'React', icon: '/images/new-images/tools/react.png' },
		{ key: 'angular', label: 'Angular', icon: '/images/new-images/tools/angular.png' },
		{ key: 'nodejs', label: 'Node JS', icon: '/images/new-images/tools/nodejs.png' },
		{ key: 'nextjs', label: 'Next JS', icon: '/images/new-images/tools/nextjs.png' },
		{ key: 'magento', label: 'Magento', icon: '/images/new-images/tools/magento.png' },
	];

	marqueeRowTop: any[] = [];
	marqueeRowBottom: any[] = [];

	constructor(
		private projectService: ProjectService,
		private router: Router,
		public translationService: TranslationService,
		private cdr: ChangeDetectorRef,
	) {
		this.imagePath = environment.baseUrl + '/public/';
		this.baseUrl = environment.url;
	}

	ngOnInit(): void {
		this.getRecentWebsites();
	}

	bookConsultation(): void {
		this.router.navigate([this.translationService.localizedPath(this.consultationLink)], {
			state: {
				service: this.serviceName.toLowerCase(),
			},
		});
	}

	getRecentWebsites(): void {
		const obj = {
			limit: 100,
			page: 1,
		};

		this.projectService.getAllProjects(obj).subscribe((response: any) => {
			if (response.code === 200) {
				const result = response.result ?? response.data ?? [];
				const websiteProjects = result.filter(
					(project: any) =>
						Array.isArray(project.dos_name) &&
						project.dos_name.some((name: string) => name.toLowerCase() === this.serviceName.toLowerCase()),
				);

				const projects = (websiteProjects.length >= 6 ? websiteProjects : result).slice(0, 8);

				this.marqueeRowTop = projects.filter((_: any, i: number) => i % 2 === 0);
				this.marqueeRowBottom = projects.filter((_: any, i: number) => i % 2 === 1);
				this.cdr.markForCheck();
			}
		});
	}

	getProjectLink(project: any): string | null {
		if (project.link && project.link !== '#') {
			return project.link;
		}
		if (project.url_key && project.url_key !== '#') {
			return this.translationService.localizedPath('/project-details/' + project.url_key);
		}
		return null;
	}

	isExternalLink(project: any): boolean {
		return !!(project.link && project.link !== '#');
	}

	projectName(project: any): string {
		return this.translationService.currentLang() === 'ar' ? project.name_ar : project.name;
	}
}
